using System;using System.IO;using UnityEngine;using UnityEditor;using Freyja.Prototype;
public static class KitWalkCheck {
 static CaisPlayerController player;static Transform cam;static double start;static Vector3 initial;static int point;static Vector2[] route={new Vector2(0,-12),new Vector2(0,12),new Vector2(-9.5f,12)};
 public static string Main(){if(!EditorApplication.isPlaying)throw new Exception("Play necessário");player=UnityEngine.Object.FindFirstObjectByType<CaisPlayerController>();var session=UnityEngine.Object.FindFirstObjectByType<CaisSessionController>();session.enabled=false;player.ControlEnabled=true;cam=GameObject.Find("Cais Gameplay Camera").transform;initial=player.transform.position;point=0;start=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;return "Percurso iniciado pelo controlador real.";}
 static void Tick(){if(!EditorApplication.isPlaying||!player){EditorApplication.update-=Tick;return;}var pos=player.transform.position;var delta=route[Math.Min(point,route.Length-1)]-new Vector2(pos.x,pos.z);if(delta.magnitude<.35f)point++;if(point>=route.Length||EditorApplication.timeSinceStartup-start>35){player.SetMoveInput(Vector2.zero);EditorApplication.update-=Tick;var json=Unity.Plastic.Newtonsoft.Json.JsonConvert.SerializeObject(new{completed=point>=route.Length,start=initial.ToString(),end=pos.ToString(),seconds=EditorApplication.timeSinceStartup-start,grounded=player.GetComponent<CharacterController>().isGrounded,method="SetMoveInput no controlador existente; sessão de input pausada apenas durante a prova"});File.WriteAllText("../Artifacts/KitPS1_022/gameplay-walk.json",json);return;}var desired=new Vector3(delta.x,0,delta.y).normalized;var forward=Vector3.ProjectOnPlane(cam.forward,Vector3.up).normalized;var right=Vector3.ProjectOnPlane(cam.right,Vector3.up).normalized;player.SetMoveInput(new Vector2(Vector3.Dot(desired,right),Vector3.Dot(desired,forward)));}
}
